# Migration Validation Script
import pandas as pd
from jira import JIRA

def validate_migration():
  redmine_df = pd.read_csv('redmine_export.csv')
  jira = JIRA(server='https://company.atlassian.net')

  validation_results = {
    'total_issues': len(redmine_df),
    'migrated_issues': 0,
    'failed_issues': [],
    'missing_attachments': [],
    'missing_comments': []
  }

  for _, row in redmine_df.iterrows():
    jql = f"project={row['project']} AND summary~'{row['subject']}'"
    issues = jira.search_issues(jql)

    if len(issues) > 0:
      validation_results['migrated_issues'] += 1

      if row['attachments_count'] != len(issues[0].fields.attachment):
        validation_results['missing_attachments'].append(issues[0].key)

      if row['comments_count'] != len(issues[0].fields.comment.comments):
        validation_results['missing_comments'].append(issues[0].key)
    else:
      validation_results['failed_issues'].append(row['id'])

  return validation_results
